      ::blink::mojom::internal::CrosDiagnostics_GetNetworkInterfaces_ResponseParams_Data> params(
          message);
  params.Allocate();
  mojo::internal::MessageFragment<decltype(params->network_interfaces)>
      network_interfaces_fragment(params.message());
  network_interfaces_fragment.Claim(&params->network_interfaces);
  mojo::internal::Serialize<::blink::mojom::GetNetworkInterfacesResultDataView>(
      in_network_interfaces, network_interfaces_fragment, true);
